from legged_gym.envs.zg_m1.zg_m1_config import ZGM1Cfg, ZGM1PPO


class ZGM1PhaseCfg(ZGM1Cfg):
    class env(ZGM1Cfg.env):
        num_observations = 59
        num_history_obs = 5 * num_observations
        num_privileged_obs = num_observations + 3 + 187

    class commands(ZGM1Cfg.commands):
        # The deployment controller supplies yaw velocity, not heading.
        heading_command = False

    class phase_gait:
        period = 1.0
        lateral_start = 0.1
        lateral_ramp = 0.1
        yaw_start = 0.1
        yaw_ramp = 0.1
        forward_start = 0.25
        forward_ramp = 0.25
        swing_clearance = 0.08                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                

    class rewards(ZGM1Cfg.rewards):
        class scales(ZGM1Cfg.rewards.scales):
            phase_clearance = -30.0                                 
            phase_swing_contact = -0.3


class ZGM1PhasePPO(ZGM1PPO):                            
    class algorithm(ZGM1PPO.algorithm):
        num_obs = 59

    class runner(ZGM1PPO.runner):
        experiment_name = "zg_m1_phase"
